export function reachAllows(places: NamedPlaces, workCountries: string[]): "yes" | "no" | "unknown" {
if (places.open) return "yes";
if (!workCountries.length) return "unknown";
if (!places.countries.length && !places.regions.length) return "unknown";
for (const c of places.countries) if (workCountries.includes(c)) return "yes";
for (const r of places.regions) if (workCountries.some((c) => regionCovers(r, c))) return "yes";
return "no";
}
```
